// Package vision implements Qwen-Image-2.1's vision tower on the CPU — the
// 27-layer ViT inside the Qwen3-VL text encoder that turns a condition
// image into the context an *edit* is conditioned on (IMAGE.md Q8).
//
// It is the largest genuinely new port of the Z-Image migration, and the
// thing to understand before reading it is what its output is for. The DiT
// overwrites every image-slot row of the joint sequence with VAE latents,
// so **none of this tensor reaches the transformer directly**. What reaches
// it is whatever the surrounding *text* tokens absorbed from these rows
// inside the text encoder's own attention. The tower conditions the text;
// the VAE conditions the pixels. That is why an edit needs both and why
// neither substitutes for the other.
//
// Five things here are not what a plain ViT would do, and each is a place a
// plausible-looking port gives a wrong answer:
//
//  1. **Token order is 2x2-block-major, not raster.** Patches are laid out
//     so that every four consecutive rows are one spatial merge block, which
//     is what lets the merger concatenate rows rather than gather. The
//     position ids carry that order (blockOrder below) and the packing of
//     pixels has to agree with it.
//  2. **The position embedding is interpolated.** The checkpoint holds
//     48x48 = 2304 learned positions and any image grid is a bilinear
//     resample of them — four (index, weight) pairs per patch, align_corners
//     true. Nothing about the grid is stored; it is recomputed per image.
//  3. **Two different GELUs.** The block MLP uses the tanh approximation
//     (config hidden_act is gelu_pytorch_tanh); both mergers use nn.GELU(),
//     which is the exact erf one. They differ by ~1e-3 at the knee, which is
//     small enough to look like noise and large enough to matter after 27
//     layers.
//  4. **Two different mergers.** The output merger normalizes each 1152-wide
//     row and *then* concatenates four of them; the three deepstack mergers
//     concatenate first and normalize the 4608-wide result
//     (use_postshuffle_norm). Their LayerNorms are different widths in the
//     checkpoint, so loading proves which is which — but running the wrong
//     one produces numbers, not an error.
//  5. **Axial rope over halves.** cos/sin are built from 18 inverse
//     frequencies per axis, concatenated h-then-w to 36 and duplicated to
//     the 72-wide head, and the rotation is the NeoX halves convention —
//     *not* the adjacent-pair complex rotation the DiT uses. The two live in
//     the same repository and are not interchangeable.
//
// Everything is gated stage by stage against reference/out/qi21vision.
package vision

import (
	"fmt"
	"math"

	"strix-halo-vulkan/zimage/qwen"
)

// Config mirrors the vision half of text_encoder/config.json.
type Config struct {
	Depth                 int    `json:"depth"`
	HiddenSize            int    `json:"hidden_size"`
	NumHeads              int    `json:"num_heads"`
	IntermediateSize      int    `json:"intermediate_size"`
	HiddenAct             string `json:"hidden_act"`
	PatchSize             int    `json:"patch_size"`
	SpatialMergeSize      int    `json:"spatial_merge_size"`
	TemporalPatchSize     int    `json:"temporal_patch_size"`
	InChannels            int    `json:"in_channels"`
	NumPositionEmbeddings int    `json:"num_position_embeddings"`
	OutHiddenSize         int    `json:"out_hidden_size"`
	DeepstackIndexes      []int  `json:"deepstack_visual_indexes"`
}

// HeadDim is the attention head width, 72 here.
func (c *Config) HeadDim() int { return c.HiddenSize / c.NumHeads }

// GridPerSide is the side of the learned position grid, 48 here.
func (c *Config) GridPerSide() int {
	return int(math.Round(math.Sqrt(float64(c.NumPositionEmbeddings))))
}

// PatchElems is how many values one patch of pixel_values carries:
// channels x temporal x patch x patch, 1536 here.
func (c *Config) PatchElems() int {
	return c.InChannels * c.TemporalPatchSize * c.PatchSize * c.PatchSize
}

// normEps is every LayerNorm's epsilon in the tower.
const normEps = 1e-6

// Linear is a row-major [Out, In] weight and an optional bias.
type Linear struct {
	In, Out int
	Weight  []float32 // [Out, In]
	Bias    []float32 // [Out] or nil

	// FP16 rounds both operands to half precision and accumulates in
	// float32, which is what a matrix-core GEMM does. It is off by default
	// and Model.SetFP16 is its only caller: this port is the fp32 oracle,
	// and the flag exists so the *cost* of the device's precision can be
	// measured before a device port is written to pay it. See
	// TestFP16Ladder.
	FP16 bool
}

// Apply computes x W^T + b over the rows of x.
func (l *Linear) Apply(x *qwen.Mat) (*qwen.Mat, error) {
	if x.Cols != l.In {
		return nil, fmt.Errorf("vision: linear %d->%d applied to %d columns", l.In, l.Out, x.Cols)
	}
	out := qwen.NewMat(x.Rows, l.Out)
	for r := 0; r < x.Rows; r++ {
		row := x.Row(r)
		dst := out.Row(r)
		if l.FP16 {
			for o := 0; o < l.Out; o++ {
				w := l.Weight[o*l.In : (o+1)*l.In]
				var acc float32
				for i, v := range row {
					acc += FP16(v) * FP16(w[i])
				}
				if l.Bias != nil {
					acc += l.Bias[o]
				}
				dst[o] = acc
			}
			continue
		}
		for o := 0; o < l.Out; o++ {
			w := l.Weight[o*l.In : (o+1)*l.In]
			var acc float64
			for i, v := range row {
				acc += float64(v) * float64(w[i])
			}
			if l.Bias != nil {
				acc += float64(l.Bias[o])
			}
			dst[o] = float32(acc)
		}
	}
	return out, nil
}

// FP16 rounds a float32 to the nearest representable half and back, ties to
// even — the rounding a value takes on when it is handed to a matrix core as
// an fp16 operand. Values past half's 65504 saturate to infinity, which is
// exactly the failure this tower has to be checked for: its residual stream
// reaches absmax 1.4e4 by the last hidden state.
func FP16(f float32) float32 {
	bits := math.Float32bits(f)
	sign := bits & 0x80000000
	exp := int32((bits>>23)&0xFF) - 127 + 15
	mant := bits & 0x7FFFFF
	switch {
	case exp >= 0x1F: // overflow, or an input that was already inf/NaN
		return math.Float32frombits(sign | 0x7F800000)
	case exp <= 0: // subnormal in half, which this model never reaches
		return math.Float32frombits(sign)
	}
	half := mant >> 13
	if rem := mant & 0x1FFF; rem > 0x1000 || (rem == 0x1000 && half&1 == 1) {
		half++
		if half == 0x400 {
			half, exp = 0, exp+1
			if exp >= 0x1F {
				return math.Float32frombits(sign | 0x7F800000)
			}
		}
	}
	return math.Float32frombits(sign | uint32(exp+127-15)<<23 | half<<13)
}

// LayerNorm is the affine, mean-subtracting norm the tower uses everywhere.
type LayerNorm struct {
	Weight, Bias []float32
}

// Apply normalizes each row in place-safe fashion, returning a fresh matrix.
func (n *LayerNorm) Apply(x *qwen.Mat) (*qwen.Mat, error) {
	if len(n.Weight) != x.Cols {
		return nil, fmt.Errorf("vision: layer norm of width %d over %d columns", len(n.Weight), x.Cols)
	}
	out := qwen.NewMat(x.Rows, x.Cols)
	for r := 0; r < x.Rows; r++ {
		row, dst := x.Row(r), out.Row(r)
		var mean float64
		for _, v := range row {
			mean += float64(v)
		}
		mean /= float64(len(row))
		var varsum float64
		for _, v := range row {
			d := float64(v) - mean
			varsum += d * d
		}
		inv := 1 / math.Sqrt(varsum/float64(len(row))+normEps)
		for i, v := range row {
			dst[i] = float32((float64(v)-mean)*inv*float64(n.Weight[i]) + float64(n.Bias[i]))
		}
	}
	return out, nil
}

// geluTanh is the block MLP's activation (config hidden_act).
func geluTanh(x float64) float64 {
package vision

import (
	"math"

	"strix-halo-vulkan/zimage/qwen"
)

// The tower's two geometric pieces, together because they share one fact:
// **the token order is 2x2-block-major, not raster**. Both the position
// grid and the rope table are indexed by that order, and so is the pixel
// packing; get it wrong and every stage still produces plausible numbers.

// blockOrder maps a token index to the (row, col) patch it holds.
//
// The reference builds it by reshaping an h x w index grid to
// (h/m, m, w/m, m), transposing the middle two axes and flattening — which
// is "walk the merge blocks in raster order, and inside each block walk its
// m x m patches in raster order". Written out rather than reshaped, because
// the transpose is the entire content of the layout and a reshape hides it.
func blockOrder(gridH, gridW, merge int) [][2]int {
	out := make([][2]int, 0, gridH*gridW)
	for by := 0; by < gridH/merge; by++ {
		for bx := 0; bx < gridW/merge; bx++ {
			for dy := 0; dy < merge; dy++ {
				for dx := 0; dx < merge; dx++ {
					out = append(out, [2]int{by*merge + dy, bx*merge + dx})
				}
			}
		}
	}
	return out
}

// positionEmbedding resamples the learned 48x48 grid onto this image's
// grid, bilinearly with align_corners.
//
// This is the piece with the most ways to be subtly wrong, so it is written
// the way the reference computes it rather than the way one would write a
// resampler: four (index, weight) pairs per patch, the weights being the
// bilinear products, and the four indices the corners of the source cell.
// align_corners means the *endpoints* map to endpoints, so the source
// coordinate of destination index i out of n is i*(48-1)/(n-1) — and for
// n == 1 that is 0 rather than a division by zero.
func (m *Model) positionEmbedding(gridH, gridW int) (*qwen.Mat, error) {
	side := m.Cfg.GridPerSide()
	dim := m.Cfg.HiddenSize
	order := blockOrder(gridH, gridW, m.Cfg.SpatialMergeSize)

	out := qwen.NewMat(len(order), dim)
	for t, rc := range order {
		sy := srcCoord(rc[0], gridH, side)
		sx := srcCoord(rc[1], gridW, side)
		y0, x0 := int(math.Floor(sy)), int(math.Floor(sx))
		y1, x1 := min(y0+1, side-1), min(x0+1, side-1)
		fy, fx := sy-float64(y0), sx-float64(x0)
		dst := out.Row(t)
		for _, c := range [4]struct {
			idx int
			w   float64
		}{
			{y0*side + x0, (1 - fy) * (1 - fx)},
			{y0*side + x1, (1 - fy) * fx},
			{y1*side + x0, fy * (1 - fx)},
			{y1*side + x1, fy * fx},
		} {
			if c.w == 0 {
				continue
			}
			row := m.PosEmbed[c.idx*dim : (c.idx+1)*dim]
			for i, v := range row {
				dst[i] += float32(c.w * float64(v))
			}
		}
	}
	return out, nil
}

// srcCoord is align_corners=true's destination-to-source map.
func srcCoord(i, n, side int) float64 {
	if n <= 1 {
		return 0
	}
	return float64(i) * float64(side-1) / float64(n-1)
}

// Rope is the tower's axial 2-D rotary table: cos and sin of [tokens,
// headDim], already in the layout the rotation reads.
//
// The frequencies are built over headDim/2 = 36 with a stride of 2, giving
// 18 per axis; h's 18 and w's 18 are concatenated to 36 and the 36
// duplicated to 72. The rotation is then **NeoX halves** -- the first half
// of the head against the second -- and not the adjacent-pair complex
// rotation the DiT's RoPE uses. Both conventions live in this repository
// and swapping them is a negative control in dit_test.go for exactly that
// reason.
type Rope struct {
	Cos, Sin *qwen.Mat
	// Pairs selects the *other* convention -- adjacent-pair complex
	// rotation, which is what qimage/dit's RoPE does. It is wrong here and
	// is selectable for exactly that reason: the two conventions live in
	// this repository, a swap between them produces numbers rather than an
	// error, and a bound that has never been shown to catch one is not a
	// bound. vision_test.go's negative control is its only caller.
	Pairs bool
}

// NewRope builds the table for one image's grid.
func NewRope(cfg *Config, gridH, gridW int) *Rope {
	hd := cfg.HeadDim()
	spatial := hd / 2
	nf := spatial / 2 // 18
	inv := make([]float64, nf)
	for i := range inv {
		inv[i] = 1 / math.Pow(10000, float64(2*i)/float64(spatial))
	}
	order := blockOrder(gridH, gridW, cfg.SpatialMergeSize)
	cos := qwen.NewMat(len(order), hd)
	sin := qwen.NewMat(len(order), hd)
	for t, rc := range order {
		c, s := cos.Row(t), sin.Row(t)
		for i, f := range inv {
			ah := float64(rc[0]) * f
			aw := float64(rc[1]) * f
			// freq_hw = [h's 18 ++ w's 18]; the table is freq_hw twice.
			for _, base := range [2]int{0, spatial} {
				c[base+i] = float32(math.Cos(ah))
				s[base+i] = float32(math.Sin(ah))
				c[base+nf+i] = float32(math.Cos(aw))
				s[base+nf+i] = float32(math.Sin(aw))
			}
		}
	}
	return &Rope{Cos: cos, Sin: sin}
}

// Apply rotates every head of every row in place, NeoX halves.
func (r *Rope) Apply(x *qwen.Mat, heads, headDim int) {
	half := headDim / 2
	for t := 0; t < x.Rows; t++ {
		row := x.Row(t)
		cos, sin := r.Cos.Row(t), r.Sin.Row(t)
		for h := 0; h < heads; h++ {
			v := row[h*headDim : (h+1)*headDim]
			if r.Pairs {
				for i := 0; i < half; i++ {
					a, b := float64(v[2*i]), float64(v[2*i+1])
					v[2*i] = float32(a*float64(cos[2*i]) - b*float64(sin[2*i]))
					v[2*i+1] = float32(b*float64(cos[2*i+1]) + a*float64(sin[2*i+1]))
				}
				continue
			}
			for i := 0; i < half; i++ {
				a, b := float64(v[i]), float64(v[i+half])
				v[i] = float32(a*float64(cos[i]) - b*float64(sin[i]))
				v[i+half] = float32(b*float64(cos[i+half]) + a*float64(sin[i+half]))
			}
		}
	}
}

// Patchify turns an image into the processor's `pixel_values`: one row per
// patch, in block-major order, each row channels-then-temporal-then-pixels.
//
// img is [3, H, W] already normalized to [-1, 1] (the processor's mean and
// std are both 0.5, so that is exactly its output), and the temporal axis is
// the same frame repeated TemporalPatchSize times — a still image entering a
// video model.
func (cfg *Config) Patchify(img []float32, h, w int) (*qwen.Mat, int, int, error) {
	p := cfg.PatchSize
	gridH, gridW := h/p, w/p
	order := blockOrder(gridH, gridW, cfg.SpatialMergeSize)
	out := qwen.NewMat(len(order), cfg.PatchElems())
	plane := h * w
	for t, rc := range order {
		dst := out.Row(t)
		i := 0
		for c := 0; c < cfg.InChannels; c++ {
			for tp := 0; tp < cfg.TemporalPatchSize; tp++ {
				for py := 0; py < p; py++ {
					srcRow := (rc[0]*p + py) * w
					for px := 0; px < p; px++ {
						dst[i] = img[c*plane+srcRow+rc[1]*p+px]
						i++
					}
				}
			}
		}
	}
	return out, gridH, gridW, nil
}

