// Merger turns `merge` consecutive tower rows into one 4096-wide row.
//
// PostShuffleNorm is the whole difference between the output merger and the
// three deepstack ones, and it moves the LayerNorm across the concatenation:
// false normalizes each 1152-wide row first, true normalizes the 4608-wide
// concatenation. The checkpoint's norm widths say which a given merger is.
type Merger struct {
	PostShuffleNorm bool
	Merge           int // rows per output row, 4 here
	Norm            LayerNorm
	FC1, FC2        Linear
	Act             func(float64) float64
}

func (m *Merger) Forward(x *qwen.Mat) (*qwen.Mat, error) {
	if x.Rows%m.Merge != 0 {
		return nil, fmt.Errorf("vision: %d rows do not group into %ds", x.Rows, m.Merge)
	}
	var shuffled *qwen.Mat
	if m.PostShuffleNorm {
		shuffled = reshape(x, m.Merge)
		normed, err := m.Norm.Apply(shuffled)
		if err != nil {
			return nil, err
		}
		shuffled = normed
	} else {
		normed, err := m.Norm.Apply(x)
		if err != nil {
			return nil, err
		}
		shuffled = reshape(normed, m.Merge)
	}
	h, err := m.FC1.Apply(shuffled)
	if err != nil {
		return nil, err
	}
	applyAct(h, m.Act)
	return m.FC2.Apply(h)
}

// reshape concatenates every `merge` consecutive rows into one. It is a
// view in torch and a copy here; at 256 rows of 1152 that is 1 MB.
func reshape(x *qwen.Mat, merge int) *qwen.Mat {
	out := qwen.NewMat(x.Rows/merge, x.Cols*merge)
	copy(out.Data, x.Data)
	return out
}

// Model is the whole tower.
type Model struct {
	Cfg Config
	// PatchProj is the Conv3d patch embedding, which at one patch per
	// window is exactly a linear over the 1536 flattened values.
	PatchProj Linear
	// PosEmbed is the [2304, 1152] learned position grid.
	PosEmbed  []float32
	Blocks    []Block
	Deepstack []Merger
	Merger    Merger
	// RopePairs forces the rotation convention qimage/dit uses, which is
	// wrong here. See Rope.Pairs: it exists so the gate can be shown to
	// catch the swap.
	RopePairs bool
}

package vision

import (
	"fmt"
	"testing"
	"time"

	"strix-halo-vulkan/vk"
	"strix-halo-vulkan/zimage/qwen"
)

const strixHaloDeviceID = 0x1586

func newTestDevice(t *testing.T) (*vk.Device, func()) {
	t.Helper()
	inst, err := vk.NewInstance("qi21-vision-test")
	if err != nil {
		t.Skipf("no Vulkan instance: %v", err)
	}
	devices, err := inst.PhysicalDevices()
	if err != nil || len(devices) == 0 {
		inst.Destroy()
		t.Skipf("no Vulkan devices: %v", err)
	}
	phys := &devices[0]
	for i := range devices {
		if devices[i].DeviceID == strixHaloDeviceID {
			phys = &devices[i]
			break
		}
	}
	qf, err := phys.ComputeQueueFamily()
	if err != nil {
		inst.Destroy()
		t.Skipf("no compute queue: %v", err)
	}
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{Float16: true, CoopMatrix: true})
	if err != nil {
		inst.Destroy()
		t.Skipf("no device: %v", err)
	}
	t.Logf("device: %s", phys.Name)
	return dev, func() { dev.Destroy(); inst.Destroy() }
}

// The bounds this port is gated at, and they are measured rather than chosen:
// TestFP16Ladder runs the CPU oracle with every linear taking fp16 operands
// and accumulating in fp32 — what a matrix core does — and reports what the
// device should therefore cost. This path does the same arithmetic on the
// device, and lands within a third of the prediction on both cards.
//
// **There are two of them, and the second is the finding.** The ladder was
// first run on the square card alone: 0.135 on the last hidden state, 0.14 on
// the merged rows, and 0.25 was the bound. Run on the *wide* card it gives
// **0.297 and 0.438** — three times as much from the same weights and the
// same code, on a picture 288 patches long instead of 256. That is not a
// second reading of one number, it is the fp16 face of what Q8.2 already
// measured in fp32: the dumped fp32 tensors are themselves rel 8.9e-4 from
