	gt.g.Tap = nil
	if gt.Tap != nil {
		gt.g.Tap = func(name string, x *qwen.Mat) {
			switch {
			case name == "embed":
				name = "vis.embed"
			case name == "post_norm":
				name = "vis.post_ln"
			case strings.HasPrefix(name, "block"):
