package ocr

import (
	"fmt"
	"strings"
)

// Tasks are the six prompts the checkpoint was trained on (the card's
// PROMPTS and PaddleX's pipeline), keyed by PaddleX's prompt labels.
var Tasks = map[string]string{
	"ocr":      "OCR:",
	"table":    "Table Recognition:",
	"formula":  "Formula Recognition:",
	"chart":    "Chart Recognition:",
	"seal":     "Seal Recognition:",
	"spotting": "Spotting:",
}

// The template's markers (chat_template.jinja). The image slot is
// <|IMAGE_PLACEHOLDER|> (config image_token_id 100295), **not** the
// <|image_pad|> the tokenizer also carries: the processor expands the
// placeholder, and a prompt built on image_pad would put the image rows
// nowhere.
const (
	tokBegin      = "<|begin_of_sentence|>"
	tokImageStart = "<|IMAGE_START|>"
	tokImage      = "<|IMAGE_PLACEHOLDER|>"
	tokImageEnd   = "<|IMAGE_END|>"
	tokEOS        = "</s>"
)

// Prompt is one request's token row: ids, the 3-D rope position of each,
// and where the image's rows go.
type Prompt struct {
	IDs []int32
	// Pos is (t, h, w) per token (OCR.md: positions).
	Pos [][3]int32
	// ImageAt is the index of the first image token; ImageLen of them follow.
	ImageAt, ImageLen int
	// Next is the position the first generated token takes. It is not
	// len(IDs): an image of mh x mw merged tokens advances the position by
	// max(mh, mw), not mh*mw. HF's rope delta is Next - len(IDs).
	Next int32
}

// BuildPrompt renders the chat template around one image of mh x mw merged
// tokens and a text, and tokenises it as the processor does: the whole
// string at once, the placeholder expanded to mh*mw copies.
func (t *Tokenizer) BuildPrompt(text string, mh, mw int) (*Prompt, error) {
	if mh <= 0 || mw <= 0 {
		return nil, fmt.Errorf("ocr: image of %dx%d merged tokens", mw, mh)
	}
	img, _ := t.ID(tokImage)
	var sb strings.Builder
	sb.WriteString(tokBegin + "User: " + tokImageStart)
	sb.WriteString(strings.Repeat(tokImage, mh*mw))
	sb.WriteString(tokImageEnd + text + "\nAssistant:\n")
	p := &Prompt{IDs: t.Encode(sb.String()), ImageAt: -1}
	p.Pos = make([][3]int32, len(p.IDs))
	var pos int32
	for i := 0; i < len(p.IDs); {
		if p.IDs[i] != img {
			p.Pos[i] = [3]int32{pos, pos, pos}
			pos++
			i++
			continue
		}
		if p.ImageAt >= 0 {
			return nil, fmt.Errorf("ocr: the prompt text holds an image token")
		}
		n := 0
		for i+n < len(p.IDs) && p.IDs[i+n] == img {
			n++
		}
		if n != mh*mw {
			return nil, fmt.Errorf("ocr: %d image tokens for a %dx%d image", n, mw, mh)
		}
		p.ImageAt, p.ImageLen = i, n
		for r := 0; r < mh; r++ {
			for c := 0; c < mw; c++ {
				p.Pos[i+r*mw+c] = [3]int32{pos, pos + int32(r), pos + int32(c)}
			}
		}
		pos += int32(max(mh, mw))
		i += n
	}
	p.Next = pos
	return p, nil
}

// EOS is `</s>`, the generation's end.
func (t *Tokenizer) EOS() int32 {
	id, _ := t.ID(tokEOS)
	return id
}
	if h < Factor {
		w = int(math.RoundToEven(float64(w*Factor) / float64(h)))
		h = Factor
	}
	if w < Factor {
		h = int(math.RoundToEven(float64(h*Factor) / float64(w)))
		w = Factor
	}
	return pixels.Processor{Factor: Factor, MinPixels: minPixels, MaxPixels: maxPixels}.SmartResize(h, w)
}

// Image is a processed image: the patches the tower's patch embedding reads,
// in raster order, and the patch grid.
type Image struct {
	// Patches is [GridH*GridW, 3, 14, 14], row-major over the patch grid.
	Patches      []float32
	GridH, GridW int
}

// MergedH and MergedW are the grid of image tokens the language model sees.
func (im *Image) MergedH() int { return im.GridH / MergeSize }
func (im *Image) MergedW() int { return im.GridW / MergeSize }

// Process is the HF processor's PIL backend: smart_resize, Pillow BICUBIC on
// the 8-bit image, then rescale and normalise with its arithmetic, which is
// two steps and not the fused one: x·(1/255) in float64 narrowed to
// float32, then (v - 0.5) / 0.5 in float32.
func Process(img *pixels.RGB, minPixels, maxPixels int) (*Image, error) {
	h, w, err := SmartResize(img.H, img.W, minPixels, maxPixels)
	if err != nil {
		return nil, err
	}
	r := pixels.ResizePillow(img, w, h)
	gh, gw := h/PatchSize, w/PatchSize
	out := &Image{Patches: make([]float32, gh*gw*PatchElems), GridH: gh, GridW: gw}
	var lut [256]float32
	for v := range lut {
		s := float32(float64(v) * 0.00392156862745098)
		lut[v] = (s - 0.5) / 0.5
	}
	for py := 0; py < gh; py++ {
		for px := 0; px < gw; px++ {
			dst := out.Patches[(py*gw+px)*PatchElems:]
			for c := 0; c < 3; c++ {
				for y := 0; y < PatchSize; y++ {
					row := r.Pix[((py*PatchSize+y)*w+px*PatchSize)*3:]
					for x := 0; x < PatchSize; x++ {
						dst[(c*PatchSize+y)*PatchSize+x] = lut[row[x*3+c]]
					}
				}
			}
		}
	}
	return out, nil
}
