package api

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"strconv"
	"strings"
	"time"
)

// POST /v1/chat/completions, buffered and streamed (LLM.md L9a).
//
// The two paths are one generation. `Complete` hands a token to a callback as
// it is produced and the two handlers differ only in what they do with it:
// the streamed one writes an SSE frame, the buffered one appends to a string
// builder. That is deliberate -- a server whose streaming path is a separate
// implementation is a server whose two answers to the same prompt eventually
// differ, and the difference always shows up as a whitespace or a marker that
// one path strips and the other does not.
//
// What this endpoint refuses is in the request validation below, and it is
// all the same refusal: it answers for what it did, not for what the field
// asked for. A `min_p` accepted and ignored is worse than a 400, because the
// client never learns that the knob it turned does nothing.

// handleChatCompletions is the OpenAI chat endpoint.
func (s *Server) handleChatCompletions(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if s.Completion == nil {
		notLoaded(ctx, w, "the language model", "-llm")
		return
	}
	var req CompletionRequest
	if !decodeJSON(ctx, w, r, &req) {
		return
	}
	model := s.completionModel(&req)
	if !validCompletion(ctx, w, &req) {
		return
	}

	id := "chatcmpl-" + randomID()
	created := time.Now().Unix()
	if req.Stream {
		s.streamCompletion(w, r, &req, id, model, created)
		return
	}

	var content, reasoning strings.Builder
	res, err := s.Completion.Complete(r.Context(), &req, func(d Delta) error {
		content.WriteString(d.Content)
		reasoning.WriteString(d.ReasoningContent)
		return nil
	})
	if err != nil {
		backendError(ctx, w, "chat completion", err)
		return
	}
	msg := &Delta{
		Role:             "assistant",
		ReasoningContent: reasoning.String(),
		Content:          content.String(),
		ToolCalls:        res.ToolCalls,
	}
	usage := res.Usage
	writeJSON(w, http.StatusOK, CompletionResponse{
		ID:      id,
		Object:  "chat.completion",
		Created: created,
		Model:   model,
		Choices: []Choice{{Index: 0, Message: msg, FinishReason: &res.FinishReason}},
		Usage:   &usage,
	})
}

// streamCompletion writes the generation as Server-Sent Events.
//
// **The status is committed before the first token**, which is what makes the
// error handling here different from every other handler in this package: by
// the time a run fails, 200 has been sent and there is no status left to
// change. So a failure becomes a final SSE frame carrying the error envelope
// -- the shape a client already parses -- and the log gets the rest.
func (s *Server) streamCompletion(w http.ResponseWriter, r *http.Request,
	req *CompletionRequest, id, model string, created int64,
) {
	ctx := r.Context()
	stream := newSSE(w)
	frame := func(v any) error { return stream.send("", v) }
	chunk := func(d *Delta, finish *string) Chunk {
		return Chunk{
			ID: id, Object: "chat.completion.chunk", Created: created, Model: model,
			Choices: []Choice{{Index: 0, Delta: d, FinishReason: finish}},
		}
	}

	// The role arrives on its own, before any content: it is what tells a
	// client which message the deltas that follow belong to.
	if err := frame(chunk(&Delta{Role: "assistant"}, nil)); err != nil {
		logf(ctx, "chat completion: %v", err)
		return
	}

	res, err := s.Completion.Complete(r.Context(), req, func(d Delta) error {
		return frame(chunk(&d, nil))
	})
	if err != nil {
		if r.Context().Err() != nil {
			// The client hung up mid-generation. There is nobody to tell.
			logf(ctx, "chat completion: client cancelled")
			return
		}
		logf(ctx, "chat completion: %v", err)
		_ = frame(errorResponse{Error: errorBody{Message: err.Error(), Type: "server_error"}})
		return
	}

	last := &Delta{}
	if len(res.ToolCalls) > 0 {
		last.ToolCalls = res.ToolCalls
	}
	if err := frame(chunk(last, &res.FinishReason)); err != nil {
		logf(ctx, "chat completion: %v", err)
		return
	}
	// OpenAI's usage chunk: an extra frame with no choices, and only when
	// the client asked for it.
	if req.StreamOptions != nil && req.StreamOptions.IncludeUsage {
		usage := res.Usage
		if err := frame(Chunk{
			ID: id, Object: "chat.completion.chunk", Created: created, Model: model,
			Choices: []Choice{}, Usage: &usage,
		}); err != nil {
			logf(ctx, "chat completion: %v", err)
			return
		}
	}
	_ = stream.done()
}

// validCompletion answers the client itself on a request this server will not
// serve, and reports whether the handler should carry on.
func validCompletion(ctx context.Context, w http.ResponseWriter, req *CompletionRequest) bool {
	if len(req.Messages) == 0 {
		badRequest(ctx, w, "messages is empty")
		return false
	}
	for i, m := range req.Messages {
		if kind := m.Content.Unreadable(); kind != "" {
			badRequest(ctx, w, "message "+strconv.Itoa(i)+" carries a "+strconv.Quote(kind)+
				" content block; this server reads text and images (image_url), and would answer about the rest alone")
			return false
		}
	}
	if req.N > 1 {
		badRequest(ctx, w, "n is "+strconv.Itoa(req.N)+
			"; this server generates one completion per request, and n of them would be n runs of a model sized to saturate the device")
		return false
	}
	if len(req.Stop) > maxStopSequences {
		badRequest(ctx, w, strconv.Itoa(len(req.Stop))+" stop sequences; this server takes at most "+
			strconv.Itoa(maxStopSequences))
		return false
	}
	for _, seq := range req.Stop {
		if seq == "" {
			badRequest(ctx, w, "a stop sequence is empty, which every generation matches immediately")
			return false
		}
	}
	if req.MinP != nil && (*req.MinP < 0 || *req.MinP > 1) {
		badRequest(ctx, w, "min_p must be between 0 and 1")
		return false
	}
	if req.RepeatPenalty != nil && *req.RepeatPenalty <= 0 {
		badRequest(ctx, w, "repeat_penalty must be positive; 1 is off")
		return false
	}
	if req.PresencePenalty != nil && (*req.PresencePenalty < -2 || *req.PresencePenalty > 2) {
		badRequest(ctx, w, "presence_penalty must be between -2 and 2")
		return false
	}
	if _, err := req.Thinking(); err != nil {
		badRequest(ctx, w, err.Error())
		return false
	}
	if req.ResponseFormat != nil && req.ResponseFormat.Type != "" && req.ResponseFormat.Type != "text" {
		badRequest(ctx, w, "response_format "+strconv.Quote(req.ResponseFormat.Type)+
			" is not implemented; there is no constrained decoding in this server yet")
		return false
	}
	return true
}

// maxStopSequences bounds `stop`. Every one of them is a string search per
// token and a tail held back from the stream, and four is what OpenAI's own
// API takes.
const maxStopSequences = 4

// modelID is what the response reports it ran. It is the backend's own id
// rather than the one the request asked for: a client configured for "gpt-4"
// against this server got this model, and saying otherwise would make a
// transcript unreadable a week later.
func modelID(b Backend, _ string) string {
	if ms := b.Models(); len(ms) > 0 {
		return ms[0].ID
	}
	return "unknown"
}

// randomID is the completion's id. It is random rather than sequential
// because it ends up in client-side logs beside other servers' ids and
// nothing should be inferable from it.
func randomID() string {
	var b [12]byte
	if _, err := rand.Read(b[:]); err != nil {
		// crypto/rand does not fail on this platform; if it ever does, a
		// timestamp is still unique enough for a log line.
		return strconv.FormatInt(time.Now().UnixNano(), 16)
	}
	return hex.EncodeToString(b[:])
}
package api

import (
	"net/http"
	"sort"
)

type ModelsResponse struct {
	Object string  `json:"object"`
	Data   []Model `json:"data"`
}

// Model represents a single model in the list of models.
type Model struct {
	ID      string `json:"id"`
	Object  string `json:"object"`   // "model"
	OwnedBy string `json:"owned_by"` // "organization_owner"
	// Voices is this model's voice names, for a speech model. It is not part
	// of OpenAI's model object -- clients ignore fields they do not know --
	// and it is here because the alternative is a second round trip to find
	// out what /v1/audio/speech will accept. A request may also name a
	// mixture of these, comma-joined, so the list is the alphabet rather
	// than the set.
	Voices []string `json:"voices,omitempty"`
	// Image is the geometry an image model will accept, and is here for the
	// same reason: the sizes /v1/images/generations takes are decided by what
	// this process staged, so a client that has to guess will guess wrong on
	// a server started at something other than 1024x1024.
	Image *ImageGeometry `json:"image,omitempty"`
	// Video is what a video model accepts, for the same reason.
	Video *VideoGeometry `json:"video,omitempty"`
	// Music is what a music model accepts.
	Music *MusicInfo `json:"music,omitempty"`
}

// backends returns every loaded backend, in the order GET /v1/models lists
// them. A nil field is a model this process was not started with.
func (s *Server) backends() []Backend {
	var out []Backend
	if s.Completion != nil {
		out = append(out, s.Completion)
	}
	if s.Embedding != nil {
		out = append(out, s.Embedding)
	}
	if s.Speech != nil {
		out = append(out, s.Speech)
	}
	if s.Transcription != nil {
		out = append(out, s.Transcription)
	}
	if s.Image != nil {
		out = append(out, s.Image)
	}
	if s.SystemOne != nil {
		out = append(out, s.SystemOne)
	}
	if s.Videos != nil {
		out = append(out, s.Videos.backend)
	}
	if s.Music != nil {
		out = append(out, s.Music.backend)
	}
	return out
}

// handleModels lists what this process actually loaded, which is the only
// honest answer: a server started without -tts does not have a speech model,
// and saying so here is cheaper for a client than a 501 later.
func (s *Server) handleModels(w http.ResponseWriter, _ *http.Request) {
	resp := ModelsResponse{Object: "list", Data: []Model{}}
	seen := map[string]bool{}
	for _, b := range s.backends() {
		for _, m := range b.Models() {
			if seen[m.ID] {
				continue
			}
			seen[m.ID] = true
			if m.Object == "" {
				m.Object = "model"
			}
			resp.Data = append(resp.Data, m)
		}
	}
	// The presets are models too, as far as a client can tell: each is a
	// name it can put in `model` and get different answers from.
	if s.Completion != nil {
		for _, p := range s.Presets {
			if !seen[p.Name] {
				seen[p.Name] = true
				resp.Data = append(resp.Data, Model{ID: p.Name, Object: "model", OwnedBy: "local"})
			}
		}
	}
	if s.Speech != nil {
		voices := s.Speech.Voices()
		sort.Strings(voices)
		for i := range resp.Data {
			if owns(s.Speech, resp.Data[i].ID) {
				resp.Data[i].Voices = voices
			}
		}
	}
	if s.Image != nil {
		geo := s.Image.Geometry()
		for i := range resp.Data {
			if owns(s.Image, resp.Data[i].ID) {
				g := geo
				resp.Data[i].Image = &g
			}
		}
	}
	if s.Videos != nil {
		geo := s.Videos.backend.VideoGeometry()
		for i := range resp.Data {
			if owns(s.Videos.backend, resp.Data[i].ID) {
				g := geo
				resp.Data[i].Video = &g
			}
		}
	}
	if s.Music != nil {
		info := s.Music.backend.MusicInfo()
		for i := range resp.Data {
			if owns(s.Music.backend, resp.Data[i].ID) {
				m := info
				resp.Data[i].Music = &m
			}
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

// owns reports whether id is one of this backend's own models, so that the
// voice list and the image geometry land on the models they describe and not
// on whatever else the process loaded beside them.
func owns(b Backend, id string) bool {
	for _, m := range b.Models() {
		if m.ID == id {
			return true
		}
	}
	return false
}
package api

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"

	"strix-halo-vulkan/util"
)

// OpenAI Chat Completion CompletionRequest
// https://platform.openai.com/docs/api-reference/chat/create
//
// The sampling fields are pointers where the zero value is a legitimate
// setting: `temperature: 0` is greedy decoding and not "unset", and a server
// that cannot tell them apart either refuses to sample or refuses to be
// deterministic. Unset takes the checkpoint's own recommendation, which this
// one carries in its metadata (`general.sampling.*`).
type CompletionRequest struct {
	ResponseFormat  *ResponseFormat `json:"response_format,omitempty"`
	StreamOptions   *StreamOptions  `json:"stream_options,omitempty"`
	ReasoningEffort string          `json:"reasoning_effort,omitempty"`
	host            string
	Model           string          `json:"model"`
	Tools           []Tool          `json:"tools,omitempty"`
	ToolChoice      json.RawMessage `json:"tool_choice,omitempty"`
	Messages        []Message       `json:"messages"`
	Stop            StringList      `json:"stop,omitempty"`
	MinP            *float64        `json:"min_p,omitempty"`
	RepeatPenalty   *float64        `json:"repeat_penalty,omitempty"`
	PresencePenalty *float64        `json:"presence_penalty,omitempty"`
	// ChatTemplateKwargs is llama-server's field: variables handed to the
	// chat template. The ones this checkpoint's template reads are
	// `enable_thinking`, `preserve_thinking` and `reasoning_effort`; any other
	// is refused, since the template here is Go and not Jinja.
	ChatTemplateKwargs map[string]json.RawMessage `json:"chat_template_kwargs,omitempty"`
	Temperature        *float64                   `json:"temperature,omitempty"`
	TopP               *float64                   `json:"top_p,omitempty"`
	TopK               *int                       `json:"top_k,omitempty"`
	Seed               *int64                     `json:"seed,omitempty"`
	MaxTokens          int                        `json:"max_tokens,omitempty"`
	// MaxCompletionTokens is OpenAI's newer spelling of MaxTokens and wins
	// when both are sent, which is what their own clients do during the
	// migration.
	MaxCompletionTokens int  `json:"max_completion_tokens,omitempty"`
	N                   int  `json:"n,omitempty"`
	Stream              bool `json:"stream"`
	// ServiceTier is OpenAI's field, read as this server's priority class
	// (CONCURRENCY.md): "priority" is interactive — a voice command, served
	// ahead of everything else — and "flex" is background. Anything else
	// takes the server's default. The X-Priority header overrides it.
	ServiceTier string `json:"service_tier,omitempty"`
}

// Budget is how many tokens the completion may run to, under either of
// OpenAI's two spellings, or zero for the server's own default.
func (r *CompletionRequest) Budget() int {
	if r.MaxCompletionTokens > 0 {
		return r.MaxCompletionTokens
	}
	return r.MaxTokens
}

// StreamOptions is OpenAI's `stream_options`. The only member that means
// anything here is the usage one.
type StreamOptions struct {
	IncludeUsage bool `json:"include_usage,omitempty"`
}

// ToolCallReq represents a tool call request
type ToolCallReq struct {
	Name      string `json:"name"`
	Arguments string `json:"arguments"`
}

// Content represents different types of content in a message
type Content struct {
	Type string `json:"type"`
	// For text content
	Text string `json:"text,omitempty"`
	// For image content
	ImageURL *struct {
		URL string `json:"url"` // base64
	} `json:"image_url,omitempty"`
	// For error content
	Error string `json:"error,omitempty"`
}

// MessageContent holds a message's content, which the OpenAI API allows as either
// a plain string or an array of content blocks. It always marshals as an array.
type MessageContent []Content

// Message represents a message from or to the LLM
type Message struct {
	Role       string         `json:"role"`                   // can be 'user', 'assistant', 'thinking', 'error' or 'tool'
	Content    MessageContent `json:"content,omitempty"`      // List of complex content (or a plain string when received)
	ToolCallID string         `json:"tool_call_id,omitempty"` // ID of the tool call
	ToolCalls  []*ToolCall    `json:"tool_calls,omitempty"`   // List of tool calls
	// ReasoningContent is an assistant turn's `<think>` block, replayed. This
	// checkpoint's template keeps the reasoning of previous turns in the
	// history, so a client that drops it is sending a different conversation
	// from the one it was shown.
	ReasoningContent string `json:"reasoning_content,omitempty"`
}

// UnmarshalJSON accepts both shapes OpenAI's schema allows for a message's
// content: a bare string, which is what most clients send, and an array of
// content blocks, which is what a multimodal message is. Both land as an
// array here, so nothing downstream has to know which arrived.
//
// A null content -- which an assistant message carrying only tool calls has
// -- decodes to no blocks rather than an error.
func (c *MessageContent) UnmarshalJSON(b []byte) error {
	trimmed := bytes.TrimSpace(b)
	switch {
	case len(trimmed) == 0 || string(trimmed) == "null":
		*c = nil
		return nil
	case trimmed[0] == '"':
		var s string
		if err := json.Unmarshal(trimmed, &s); err != nil {
			return err
		}
		*c = MessageContent{{Type: "text", Text: s}}
		return nil
	default:
		var parts []Content
		if err := json.Unmarshal(trimmed, &parts); err != nil {
			return err
		}
		*c = parts
		return nil
	}
}

// Text is the message's text blocks joined, which is what a text-only model
// is given. Blocks of any other type are skipped rather than rendered, so an
// image in a conversation does not arrive as a caption the model would read
// as words.
func (c MessageContent) Text() string {
	var b strings.Builder
	for _, part := range c {
		if part.Type == "" || part.Type == "text" {
			b.WriteString(part.Text)
		}
	}
	return b.String()
}

// HasImage is whether any block is an image (`image_url`), which is what
// makes a message the template's content list rather than one string.
func (c MessageContent) HasImage() bool {
	for _, part := range c {
		if part.Type == "image_url" {
			return true
		}
	}
	return false
}

// Unreadable is the first content block that is neither text nor an image,
// or the empty string. It is what the chat handler refuses on: a block the
// model cannot read would be dropped silently and answered about as though it
// had never been sent (audio, video, a file).
func (c MessageContent) Unreadable() string {
	for _, part := range c {
		if part.Type != "" && part.Type != "text" && part.Type != "image_url" {
			return part.Type
		}
	}
	return ""
}

// Thinking is a request's reasoning switches, resolved from the two
// vocabularies it can arrive in: OpenAI's `reasoning_effort` and the
// template's own variables in `chat_template_kwargs`.
type Thinking struct {
	// Off is `enable_thinking=false`.
	Off bool
	// Effort is "", "low", "medium", "high" or "xhigh"; empty is the
	// template's default.
	Effort string
	// DropHistory is `preserve_thinking=false`.
	DropHistory bool
}

// Thinking resolves the request's reasoning switches.
//
// The top-level `reasoning_effort` is the client's own -- a preset writes
// `chat_template_kwargs` and clears it (see Preset.Apply) -- so when it is
// set it decides on and off outright. Otherwise `enable_thinking` does, and a
// `reasoning_effort` of "none" in the kwargs means off only when
// `enable_thinking` is absent: a client that sends `enable_thinking: true`
// to a non-thinking preset gets thinking, whatever effort the preset named.
func (r *CompletionRequest) Thinking() (Thinking, error) {
	var t Thinking
	var enable *bool
	var effort string
	for k, v := range r.ChatTemplateKwargs {
		var err error
		switch k {
		case "enable_thinking":
			var b bool
			err = json.Unmarshal(v, &b)
			enable = &b
		case "preserve_thinking":
			var b bool
			err = json.Unmarshal(v, &b)
			t.DropHistory = !b
		case "reasoning_effort":
			err = json.Unmarshal(v, &effort)
		default:
			return t, fmt.Errorf("chat_template_kwargs.%s is not a variable this checkpoint's template reads; "+
				"it takes enable_thinking, preserve_thinking and reasoning_effort", k)
		}
		if err != nil {
			return t, fmt.Errorf("chat_template_kwargs.%s: %v", k, err)
		}
	}
	effort = strings.ToLower(effort)
	off := effort == "none" || effort == "minimal"
	if enable != nil {
		off = !*enable
	}
	if r.ReasoningEffort != "" {
		effort = strings.ToLower(r.ReasoningEffort)
		off = effort == "none" || effort == "minimal"
	}
	t.Off = off
	if !off && effort != "none" && effort != "minimal" {
		t.Effort = effort
	}
	return t, nil
}

