// Message represents a message from or to the LLM
type Message struct {
	Role       string         `json:"role"`                   // can be 'user', 'assistant', 'thinking', 'error' or 'tool'
	Content    MessageContent `json:"content,omitempty"`      // List of complex content (or a plain string when received)
	ToolCallID string         `json:"tool_call_id,omitempty"` // ID of the tool call
	ToolCalls  []*ToolCall    `json:"tool_calls,omitempty"`   // List of tool calls
	// ReasoningContent is an assistant turn's `<think>` block, replayed. This
	// checkpoint's template keeps the reasoning of previous turns in the
	// history, so a client that drops it is sending a different conversation
	// from the one it was shown.
	ReasoningContent string `json:"reasoning_content,omitempty"`
}

// UnmarshalJSON accepts both shapes OpenAI's schema allows for a message's
// content: a bare string, which is what most clients send, and an array of
// content blocks, which is what a multimodal message is. Both land as an
// array here, so nothing downstream has to know which arrived.
//
// A null content -- which an assistant message carrying only tool calls has
// -- decodes to no blocks rather than an error.
func (c *MessageContent) UnmarshalJSON(b []byte) error {
	trimmed := bytes.TrimSpace(b)
	switch {
	case len(trimmed) == 0 || string(trimmed) == "null":
		*c = nil
		return nil
	case trimmed[0] == '"':
		var s string
		if err := json.Unmarshal(trimmed, &s); err != nil {
			return err
		}
		*c = MessageContent{{Type: "text", Text: s}}
		return nil
	default:
		var parts []Content
		if err := json.Unmarshal(trimmed, &parts); err != nil {
			return err
		}
		*c = parts
		return nil
	}
}

// Text is the message's text blocks joined, which is what a text-only model
// is given. Blocks of any other type are skipped rather than rendered, so an
// image in a conversation does not arrive as a caption the model would read
// as words.
func (c MessageContent) Text() string {
	var b strings.Builder
	for _, part := range c {
		if part.Type == "" || part.Type == "text" {
			b.WriteString(part.Text)
		}
	}
	return b.String()
}

// HasImage is whether any block is an image (`image_url`), which is what
// makes a message the template's content list rather than one string.
func (c MessageContent) HasImage() bool {
	for _, part := range c {
		if part.Type == "image_url" {
			return true
		}
	}
	return false
}

// Unreadable is the first content block that is neither text nor an image,
// or the empty string. It is what the chat handler refuses on: a block the
// model cannot read would be dropped silently and answered about as though it
// had never been sent (audio, video, a file).
func (c MessageContent) Unreadable() string {
	for _, part := range c {
		if part.Type != "" && part.Type != "text" && part.Type != "image_url" {
			return part.Type
		}
	}
	return ""
}

// Thinking is a request's reasoning switches, resolved from the two
// vocabularies it can arrive in: OpenAI's `reasoning_effort` and the
// template's own variables in `chat_template_kwargs`.
type Thinking struct {
	// Off is `enable_thinking=false`.
	Off bool
	// Effort is "", "low", "medium", "high" or "xhigh"; empty is the
	// template's default.
	Effort string
	// DropHistory is `preserve_thinking=false`.
	DropHistory bool
}

// Thinking resolves the request's reasoning switches.
//
// The top-level `reasoning_effort` is the client's own -- a preset writes
// `chat_template_kwargs` and clears it (see Preset.Apply) -- so when it is
// set it decides on and off outright. Otherwise `enable_thinking` does, and a
// `reasoning_effort` of "none" in the kwargs means off only when
// `enable_thinking` is absent: a client that sends `enable_thinking: true`
// to a non-thinking preset gets thinking, whatever effort the preset named.
func (r *CompletionRequest) Thinking() (Thinking, error) {
	var t Thinking
	var enable *bool
	var effort string
	for k, v := range r.ChatTemplateKwargs {
		var err error
		switch k {
		case "enable_thinking":
			var b bool
			err = json.Unmarshal(v, &b)
			enable = &b
		case "preserve_thinking":
			var b bool
			err = json.Unmarshal(v, &b)
			t.DropHistory = !b
		case "reasoning_effort":
			err = json.Unmarshal(v, &effort)
		default:
			return t, fmt.Errorf("chat_template_kwargs.%s is not a variable this checkpoint's template reads; "+
				"it takes enable_thinking, preserve_thinking and reasoning_effort", k)
		}
		if err != nil {
			return t, fmt.Errorf("chat_template_kwargs.%s: %v", k, err)
		}
	}
	effort = strings.ToLower(effort)
	off := effort == "none" || effort == "minimal"
	if enable != nil {
		off = !*enable
	}
	if r.ReasoningEffort != "" {
		effort = strings.ToLower(r.ReasoningEffort)
		off = effort == "none" || effort == "minimal"
	}
	t.Off = off
	if !off && effort != "none" && effort != "minimal" {
		t.Effort = effort
	}
	return t, nil
}

