// Complete renders the conversation, prefills it and decodes until something
// stops it.
//
// The whole request is one sequence in one graph, which is why it is
// serialised: the attention cache, the PLE convolution's ring and every
// DeltaNet layer's recurrent state carry from token to token (LLM.md L7b),
// and they are the conversation. A second conversation interleaved into them
// would not be slower, it would be wrong.
func (l *LLM) Complete(ctx context.Context, req *api.CompletionRequest,
	emit func(api.Delta) error,
) (_ *api.CompletionResult, err error) {
	// enter is what the *client's* clock started at, as near as this side can
	// see it: everything below -- rendering the template, tokenizing, waiting
	// for the graph another request is holding, and the prefill -- is time
	// before the first token arrives, so it is all in the time to first token
	// this reports.
	enter := time.Now()
	msgs, opt, images, err := chatRequest(req)
	if err != nil {
		return nil, err
	}
	// The template before the pixels: a conversation it refuses (an image in
	// a system turn) costs nothing to refuse.
	prompt, err := llm.RenderChat(msgs, opt)
	if err != nil {
		return nil, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	// The images before a slot is taken: each is a tower pass on the
	// device, and holding a slot through them would keep a conversation
	// out for nothing.
	var prompted []llm.PromptImage
	var tower time.Duration
	class := l.classOf(ctx, req)
	l.closeMu.Lock()
	sched := l.sched
	l.closeMu.Unlock()
	if sched == nil {
		return nil, fmt.Errorf("the language model is closed")
	}
	if len(images) > 0 {
		if l.vision == nil {
			return nil, fmt.Errorf("this server was started without the vision tower, so an image would be "+
				"answered about as though it had not been sent; start it with -llm-mmproj: %w", api.ErrUnsupported)
		}
		if len(images) > l.opt.VisionImages {
			return nil, fmt.Errorf("%d images in one request; this server takes at most %d: %w",
				len(images), l.opt.VisionImages, api.ErrUnsupported)
		}
		// Fetched before the tower is taken: a URL is a download of
		// unknown length, and the device is not held for it. OpenAI's API
		// fetches an image_url, so this one does too (util.FetchImage).
		for i := range images {
			if images[i].data, err = util.FetchImage(ctx, images[i].url); err != nil {
				return nil, fmt.Errorf("image %d: %v: %w", i, err, api.ErrUnsupported)
			}
		}
		done := sched.towerBegin(class)
		for _, im := range images {
			p, took, err := l.vision.encode(ctx, l.opt.Device, im)
			if err != nil {
				done()
				return nil, err
			}
			prompted, tower = append(prompted, p), tower+took
		}
		done()
	}
	short, err := l.tok.Encode(prompt)
	if err != nil {
		return nil, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	if len(short) == 0 {
		return nil, fmt.Errorf("the conversation tokenizes to nothing: %w", api.ErrUnsupported)
	}
	in, err := llm.ExpandImages(short, imagePad, prompted)
	if err != nil {
		return nil, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	ids := in.IDs
	keys := promptKeys(in)
	// The cache is the residency this process was started with, so a
	// conversation past it is refused with the number rather than truncated
	// at one end or the other -- both of which change the answer without
	// saying so.
	if len(ids) >= l.opt.Context {
		return nil, fmt.Errorf(
			"the conversation is %d tokens and this server staged a %d-cell cache; start it with a larger -llm-ctx: %w",
			len(ids), l.opt.Context, api.ErrUnsupported)
	}
	budget := req.Budget()
	if budget <= 0 {
		budget = l.opt.MaxTokens
	}
	if room := l.opt.Context - len(ids); budget > room {
		budget = room
	}

	wait := time.Now()
	job, err := sched.acquire(ctx, class, keys, l.checkpointAt(prompt, short, prompted))
	if err != nil {
		return nil, err
	}
	defer sched.release(job)
	// queued is how long this request waited for a slot: every slot held by
	// another conversation. It is reported separately because it is the one
	// part of a slow time to first token that is not this request's own
	// work, and without it a turn that waited eight seconds looks like a
	// turn whose prefill was eight seconds. stalled is the other kind of
	// wait: time its own units spent queued behind other conversations'
	// units once it had a slot (CONCURRENCY.md C2).
	// Measured from here rather than from enter since images: the tower's
	// time before it is this request's own work, reported beside it.
	queued := time.Since(wait)

func (v *llmVision) close() {
	if v != nil && v.gpu != nil {
		v.gpu.Destroy()
	}
}

// requestImage is one image as the request sent it, in conversation order:
// its URL, and once fetched (util.FetchImage, before the tower is taken)
// its bytes.
type requestImage struct {
	url  string
	data []byte
}

// encode turns one image into the prompt's rows. It returns the tower time
// for the request's log line: wall time, including the units that ran in its
// yields.
//
// The tower yields the device every v.slice to whoever is waiting for it.
// It is still one pass as far as its arenas go (v.tower), and an interactive
// request's tower counts as an interactive job to the scheduler (towerBegin),
// so what runs in its gaps is another interactive unit and never a
// background prefill chunk.
func (v *llmVision) encode(ctx context.Context, dev *Device, img requestImage) (llm.PromptImage, time.Duration, error) {
	data := img.data
	sum := sha256.Sum256(data)
	hash := binary.LittleEndian.Uint64(sum[:8])
	if p, ok := v.lookup(hash); ok {
		return p, 0, nil
	}
	rgb, _, err := pixels.Decode(data)
	if err != nil {
		return llm.PromptImage{}, 0, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	planes, h, w, err := v.proc.Planes(rgb)
	if err != nil {
		return llm.PromptImage{}, 0, fmt.Errorf("%v: %w", err, api.ErrUnsupported)
	}
	rows, gh, gw, err := v.cfg.Patchify(planes, h, w)
	if err != nil {
		return llm.PromptImage{}, 0, err
	}
	var out *vision.Output
	v.tower.Lock()
	defer v.tower.Unlock()
	start := time.Now()
	held := start
	v.gpu.Between = nil
	if v.slice > 0 {
		v.gpu.Between = func() {
			if time.Since(held) >= v.slice {
				dev.yield()
				held = time.Now()
			}
		}
	}
	err = dev.Do(func(*vk.Device) error {
		var err error
		out, err = v.gpu.Forward(ctx, rows, gh, gw)
		return err
	})
	if err != nil {
		return llm.PromptImage{}, 0, fmt.Errorf("vision tower: %w", err)
	}
	p := llm.PromptImage{
		GridH: gh / v.cfg.SpatialMergeSize, GridW: gw / v.cfg.SpatialMergeSize,
		Hash: hash, Embd: out.Merged.Data,
	}
	v.store(p)
	return p, time.Since(start), nil
}

