package backend

import (
	"fmt"
	"sync"

	"strix-halo-vulkan/vk"
)

const strixHaloDeviceID = 0x1586

type Device struct {
	inst *vk.Instance
	dev  *vk.Device
	mu   fifoLock
}

type fifoLock struct {
	mu    sync.Mutex
	held  bool
	queue []chan struct{}
}

func (l *fifoLock) Lock() {
	l.mu.Lock()
	if !l.held {
		l.held = true
		l.mu.Unlock()
		return
	}
	ch := make(chan struct{})
	l.queue = append(l.queue, ch)
	l.mu.Unlock()
	<-ch // the lock is handed over held
}

func (l *fifoLock) Unlock() {
	l.mu.Lock()
	defer l.mu.Unlock()
	if !l.held {
		panic("backend: unlock of an unlocked device")
	}
	if len(l.queue) == 0 {
		l.held = false
		return
	}
	close(l.queue[0])
	l.queue = l.queue[1:]
}

