package layout

import (
	"math"
	"sort"

	"strix-halo-vulkan/llm/pixels"
)

// Preprocess is HF's PPDocLayoutV3ImageProcessor: an 800x800 bicubic resize
// *without* antialiasing (it stands in for PaddleX's cv2.INTER_CUBIC) on the
// 8-bit image, rounded back to 8 bits, then x/255, as [3][800][800].
//
// The resize is torch's upsample_bicubic2d: A = -0.75, source coordinate
// (i + 0.5)*in/out - 0.5 unclamped, four taps at floor-1..floor+2 with their
// indices clamped to the edge, float32 arithmetic, then round-half-even and
// a clamp to [0, 255] (torchvision's uint8 path).
func Preprocess(img *pixels.RGB) []float32 {
	const n = InputSize
	out := make([]float32, 3*n*n)
	xs := cubicTaps(img.W, n)
	ys := cubicTaps(img.H, n)
	parallel(n, func(oy int) {
		ty := ys[oy]
		for ox := 0; ox < n; ox++ {
			tx := xs[ox]
			for c := 0; c < 3; c++ {
				var acc float32
				for j := 0; j < 4; j++ {
					row := img.Pix[ty.idx[j]*img.W*3:]
					var h float32
					for i := 0; i < 4; i++ {
						h += tx.w[i] * float32(row[tx.idx[i]*3+c])
					}
					acc += ty.w[j] * h
				}
				v := float32(math.RoundToEven(float64(acc)))
				v = min(max(v, 0), 255)
				out[(c*n+oy)*n+ox] = v * float32(1.0/255)
			}
		}
	})
	return out
}

type cubicTap struct {
	idx [4]int
	w   [4]float32
}

// cubicTaps is each output index's four source indices and weights.
func cubicTaps(in, out int) []cubicTap {
	const A = -0.75
	scale := float32(in) / float32(out)
	cc1 := func(x float32) float32 { return ((A+2)*x-(A+3))*x*x + 1 }
	cc2 := func(x float32) float32 { return ((A*x-5*A)*x+8*A)*x - 4*A }
	taps := make([]cubicTap, out)
	for i := range taps {
		s := scale*(float32(i)+0.5) - 0.5
		f := float32(math.Floor(float64(s)))
		t := s - f
