// projOverlap is layout_parsing/utils.py calculate_projection_overlap_ratio,
// horizontal, union.
func projOverlap(a, b [4]int) float64 {
	o := min(a[2], b[2]) - max(a[0], b[0])
	if o <= 0 {
		return 0
	}
	return float64(o) / float64(max(a[2], b[2])-min(a[0], b[0]))
