					b := blocks[i]
					b.GroupID = g.indices[0]
					if j == 0 {
						b.Img, b.MergeAligns = m, append([]string{}, g.aligns...)
					} else {
						b.Img, b.MergeAligns = nil, nil
					}
					out = append(out, b)
					used[i] = true
				}
			}
			for n := start + 1; n < end; n++ {
				if nonMergeIdx[n] {
					out = append(out, blocks[n])
					used[n] = true
				}
			}
			idx = end + 1
			break
		}
		if found {
			continue
		}
		if nonMergeIdx[idx] && !used[idx] {
			out = append(out, blocks[idx])
			used[idx] = true
		}
		idx++
	}
